#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);
}

int main(void) {
    int T, N;
    scanf("%d", &T);
    scanf("%d", &N);

    int *x = (int *)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &x[i]);
    }

    qsort(x, N, sizeof(int), cmp);

    double ans = 1e18;

    double first = (x[0] + x[1]) / 2.0;
    if (first < ans) ans = first;

    for (int i = 1; i < N - 1; i++) {
        double len = (x[i + 1] - x[i - 1]) / 2.0;
        if (len < ans) ans = len;
    }

    double last = T - (x[N - 2] + x[N - 1]) / 2.0;
    if (last < ans) ans = last;

    printf("%.2f\n", ans);

    free(x);
    return 0;
}
